import os
from pydantic_settings import BaseSettings
from typing import List, Optional
from dotenv import load_dotenv

# Load .env.local (generated by Vercel CLI) and .env
load_dotenv(".env.local")
load_dotenv(".env")


class Settings(BaseSettings):
    # Database configuration
    DATABASE_URL: str = os.getenv(
        "POSTGRES_URL",
        os.getenv("DATABASE_URL", "postgresql://postgres:postgres@localhost:5432/gc_seg_db")
    )

    # Environment
    ENVIRONMENT: str = os.getenv("ENVIRONMENT", "development")

    # Cloudflare Turnstile (replaces Google reCAPTCHA)
    TURNSTILE_SECRET_KEY: Optional[str] = os.getenv("TURNSTILE_SECRET_KEY", None)
    TURNSTILE_SITE_KEY: Optional[str] = os.getenv("TURNSTILE_SITE_KEY", None)

    # JWT & admin authentication
    JWT_SECRET_KEY: str = os.getenv("JWT_SECRET_KEY", "giaconi-capra-pas-jwt-secret-key-prod-2026")
    JWT_ALGORITHM: str = os.getenv("JWT_ALGORITHM", "HS256")
    JWT_ACCESS_TOKEN_EXPIRE_MINUTES: int = int(os.getenv("JWT_ACCESS_TOKEN_EXPIRE_MINUTES", "480")) # 8 hours

    # CORS
    ALLOWED_ORIGINS: str = os.getenv("ALLOWED_ORIGINS", "*")

    @property
    def sqlalchemy_database_url(self) -> str:
        url = self.DATABASE_URL.strip()
        # Normalize legacy schemes: Vercel/Neon integrations usually inject
        # "postgres://"; SQLAlchemy expects "postgresql://".
        if url.startswith("postgres://"):
            url = "postgresql://" + url[len("postgres://"):]
        # The DBAPI driver is NEVER decided by the URL: it is decided by the
        # installed package (psycopg v3, pinned in requirements.txt). Some
        # environments inject driver suffixes ("postgresql+psycopg://",
        # "+psycopg2", ...); if the matching package is not installed,
        # create_engine explodes at import time and takes down the ENTIRE
        # serverless function (FUNCTION_INVOCATION_FAILED).
        if url.startswith("postgresql+"):
            url = "postgresql://" + url.split("://", 1)[1]
        return url

    @property
    def cors_origins(self) -> List[str]:
        if self.ALLOWED_ORIGINS == "*":
            return ["*"]
        return [origin.strip() for origin in self.ALLOWED_ORIGINS.split(",") if origin.strip()]

    class Config:
        env_file = ".env"
        extra = "ignore"

settings = Settings()
